import unittest
from unittest.mock import Mock
from pylint.inspector import ClassInspector

class TestInspector(unittest.TestCase):
    def test_annotations(self):
        node = Mock(annotations={'x': 'int', 'y': 'str'})
        insp = ClassInspector()
        self.assertEqual(insp.inspect(node), {'x': 'int', 'y': 'str'})

if __name__ == '__main__': unittest.main()
